//! 🧪️ The actual retained mounted-command state admits the same framed source and closes under the original caller.
use super::*;
use crate::{WindowConfigOwner,WindowConfigOwnerRegistry};
use crate::original_genesis_tests::Owner;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,default_now_us,close_original_retained_step};
use semio_framework_value::{RetainedCloneGrant,ToValue};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
thread_local!{static CURSOR:std::cell::Cell<(u64,u8,u8)>=const{std::cell::Cell::new((0,0,0))};}
fn note(index:u64,command:&WindowConfigCommandLoad){CURSOR.with(|cursor|cursor.set((index,u8::from(command.closing)|u8::from(command.done)<<1|u8::from(command.pack.is_some())<<2|u8::from(command.load.is_some())<<3,u8::from(command.failure.is_some())|u8::from(command.close_failure.is_some())<<1|u8::from(command.compound.is_some())<<2)));}
fn law()->serde_json::Value{serde_json::from_str(include_str!("🔣️.json")).unwrap()}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:2<<20,maximum_depth:128}}
fn caller()->OriginalJobFixtureCaller{let law=law();OriginalJobFixtureCaller::admit(OperationId(law["operation"].as_u64().unwrap()),Generation(law["generation"].as_u64().unwrap()),RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<29,maximum_capacity_bytes:1<<26,maximum_release_bytes:1<<26,maximum_depth:4096},default_now_us,u64::MAX,1<<28)}
fn entry()->protocol::WindowConfigPackEntry{let input=crate::retained::typed_pack_load::original_saved_input(true);let WindowConfigPackSource::Framed(envelope_pack)=input.source else{unreachable!()};protocol::WindowConfigPackEntry{window_id:input.window_id,window_kind_id:input.window_kind_id,envelope_pack}}
fn turn<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->Result<T,OriginalTurnFailure>{let(result,heap)=observe(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"mounted Window command receipt differs {p:?}; cause {:?}; cursor {:?}",result.as_ref().err(),CURSOR.with(std::cell::Cell::get));result}
fn finish(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,registry:&mut WindowConfigOwnerRegistry){let maximum=law()["maximumTurns"].as_u64().unwrap();for index in 0..maximum{if registry.terminal_is_empty(){break}turn(caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|registry.close_step_context(cx.retained_grant(),cx).map(|_|()).map_err(Into::into))).unwrap();assert!(index+1<maximum,"actual Window command registry retirement did not close");}assert!(registry.terminal_is_empty());while !decoder.terminal_is_empty(){caller.turn(grant(),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}}
#[test]
fn original_mounted_window_command_admits_exact_framed_source_and_native_state(){let law=law();let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut registry=WindowConfigOwnerRegistry::new(protocol::ActorId("mounted-reader".into()));registry.register::<Owner>().unwrap();let mut entry=entry();let pointer=entry.envelope_pack.as_ptr();let mut command=WindowConfigCommandLoad::default();let mut done=false;for index in 0..law["maximumTurns"].as_u64().unwrap(){note(index,&command);done=turn(&mut caller,&mut decoder,grant(),|cx|command.advance(&mut registry,&mut entry,cx)).unwrap();if index==0{assert!(entry.envelope_pack.is_empty());let source=&command.pack.as_ref().unwrap().source;let WindowConfigPackSource::Framed(bytes)=source else{unreachable!()};assert_eq!(bytes.as_ptr(),pointer)}if command.load.as_ref().is_some_and(|load|matches!(load.phase(),WindowConfigPackLoadPhase::EnvelopeIdentity|WindowConfigPackLoadPhase::HistoryReplay|WindowConfigPackLoadPhase::StoreHydration)){assert!(registry.borrow(Owner::WINDOW_KIND_ID,"camera-left").is_none())}if done{break}assert!(index+1<law["maximumTurns"].as_u64().unwrap());}assert!(done&&command.terminal_is_empty());let state=registry.borrow(Owner::WINDOW_KIND_ID,"camera-left").unwrap().get::<Owner>().unwrap().to_value();assert_eq!(state,semio_framework_value::DslValue::Object(vec![("zoom".into(),law["expectedZoom"].as_f64().unwrap().to_value())]));finish(&mut caller,&mut decoder,&mut registry);caller.retire(grant());}
fn cancel(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,registry:&mut WindowConfigOwnerRegistry,entry:&mut protocol::WindowConfigPackEntry,command:&mut WindowConfigCommandLoad){caller.cancel().cancel_now();let mut failure=None;for index in 0..262144{note(index,command);match turn(caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|command.advance(registry,entry,cx))){Ok(done)=>assert!(!done),Err(cause)=>{assert!(command.terminal_is_empty());failure=Some(cause);break}}assert!(index<262143,"cancel did not close: {:?}; {}; fuel{} receipt{:?}",CURSOR.with(std::cell::Cell::get),crate::retained::typed_pack_load::original_saved_diagnostic(&command.load),caller.fuel_remaining(),caller.receipt())}assert!(failure.is_some());let mut close=None;while failure.is_some()||close.is_some(){turn(caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|{let d=semio_framework_plugin_ownership::bounded_ownership::plugin_typed_owner_demand(&failure,&close,cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|semio_framework_plugin_ownership::bounded_ownership::plugin_typed_owner_step(&mut failure,&mut close,g))?;Ok(())})).unwrap();}}
#[test]
fn original_mounted_window_command_denied_axes_preserve_entry_and_allocate_nothing(){for axis in law()["deniedAxes"].as_array().unwrap(){let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut registry=WindowConfigOwnerRegistry::new(protocol::ActorId("denied-reader".into()));registry.register::<Owner>().unwrap();let mut entry=entry();let pointer=entry.envelope_pack.as_ptr();let original=(entry.window_id.clone(),entry.window_kind_id.clone(),entry.envelope_pack.len());let mut command=WindowConfigCommandLoad::default();let mut denied=grant();match axis.as_str().unwrap(){"items"=>denied.maximum_items=0,"copy"=>denied.maximum_copy_bytes=0,"capacity"=>denied.maximum_capacity_bytes=0,"release"=>denied.maximum_release_bytes=0,"depth"=>denied.maximum_depth=0,_=>unreachable!()}let result=turn(&mut caller,&mut decoder,denied,|cx|command.advance(&mut registry,&mut entry,cx)).unwrap();assert!(!result);if matches!(axis.as_str().unwrap(),"items"|"copy"|"depth"){assert!(command.terminal_is_empty());assert_eq!(entry.envelope_pack.as_ptr(),pointer);assert_eq!((&entry.window_id,&entry.window_kind_id,entry.envelope_pack.len()),(&original.0,&original.1,original.2))}else{let WindowConfigPackSource::Framed(bytes)=&command.pack.as_ref().unwrap().source else{unreachable!()};assert_eq!(bytes.as_ptr(),pointer);if axis=="capacity"{assert!(!turn(&mut caller,&mut decoder,denied,|cx|command.advance(&mut registry,&mut entry,cx)).unwrap());assert!(command.load.is_none());assert_eq!(caller.receipt().retained_capacity_bytes,0);}}cancel(&mut caller,&mut decoder,&mut registry,&mut entry,&mut command);assert!(command.terminal_is_empty());finish(&mut caller,&mut decoder,&mut registry);caller.retire(grant());}}
#[test]
fn original_mounted_window_command_cancellation_retires_partial_native_sources(){for cut in law()["cancelAt"].as_array().unwrap(){let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut registry=WindowConfigOwnerRegistry::new(protocol::ActorId("cancel-reader".into()));registry.register::<Owner>().unwrap();let mut entry=entry();let mut command=WindowConfigCommandLoad::default();for _ in 0..cut.as_u64().unwrap(){assert!(!turn(&mut caller,&mut decoder,grant(),|cx|command.advance(&mut registry,&mut entry,cx)).unwrap())}cancel(&mut caller,&mut decoder,&mut registry,&mut entry,&mut command);assert!(command.terminal_is_empty());assert!(registry.borrow(Owner::WINDOW_KIND_ID,"camera-left").is_none());finish(&mut caller,&mut decoder,&mut registry);caller.retire(grant());}}

#[test]
fn original_mounted_window_command_release_denial_preserves_original_closure(){let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut registry=WindowConfigOwnerRegistry::new(protocol::ActorId("release-reader".into()));registry.register::<Owner>().unwrap();let mut entry=entry();let mut command=WindowConfigCommandLoad::default();assert!(!turn(&mut caller,&mut decoder,grant(),|cx|command.advance(&mut registry,&mut entry,cx)).unwrap());caller.cancel().cancel_now();let mut denied=grant();denied.maximum_release_bytes=0;let mut verified=false;for index in 0..262144{let d=semio_framework_plugin_ownership::bounded_ownership::plugin_typed_owner_demand(&command.pack,&command.pack_close,denied.maximum_copy_bytes).unwrap();assert!(!turn(&mut caller,&mut decoder,denied,|cx|cx.with_original_retirement(|cx|command.advance(&mut registry,&mut entry,cx))).unwrap());if d.release_bytes>0{assert_eq!(caller.receipt(),Default::default());assert!(command.pack.is_some()||command.pack_close.is_some());verified=true;break}assert!(index<262143)}assert!(verified);cancel(&mut caller,&mut decoder,&mut registry,&mut entry,&mut command);finish(&mut caller,&mut decoder,&mut registry);caller.retire(grant());}
